import{_ as o,l,o as e,c as s,v as r,p as n,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"PIR","description":"","frontmatter":{"title":"PIR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pir.md","filePath":"cs/pir.md","lastUpdated":1789023840000}'),c={name:"cs/pir.md"};function P(_,a,u,m,f,E){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="pir" tabindex="-1">PIR <a class="header-anchor" href="#pir" aria-label="Permalink to &quot;PIR&quot;">​</a></h1><div class="epigraph"><p>私有信息检索让用户从服务器取第 i 条，而不让服务器知道 i。信息论 PIR 要多服务器；计算 PIR 用同态，更重。索引隐私与内容保密不是同一句话。</p><footer>—— Chor, Goldreich, Kushilevitz and Sudan, Private Information Retrieval, JACM 1998</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/mpc-applications">MPC</a>是多方表。缺口是<strong>单用户对数据库的查询隐私</strong>。本课 PIR 直觉。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HTTPS 仍让服务器看见 URL 或索引。PIR：服务器不知 i。缺口是通信膨胀与恶意服务器。</p><h3 id="不是匿名网" tabindex="-1">不是匿名网 <a class="header-anchor" href="#不是匿名网" aria-label="Permalink to &quot;不是匿名网&quot;">​</a></h3><p>PIR 不藏网络身份；Tor 后课管路由。</p><p><span class="marginnote">CGKS 1998。Tor 下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照下载全集（平凡 PIR）。多服务器异或构造点名。下一课 Tor。</p>',12)),(e(),n(h,null,{default:i(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%B4%A2%E5%BC%95%20i%22%5D%20--%3E%20PIR%5B%22%E6%A3%80%E7%B4%A2%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20PIR%20--%3E%20REC%5B%22%E8%AE%B0%E5%BD%95%22%5D%0A%20%20SRV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%20-.-%3E%7C%22%E4%B8%8D%E7%9F%A5%20i%22%7C%20PIR%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>查询隐私。Tor 把 IP 与目的藏进接力。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写实现作业当攻击。Tor 洋葱路由下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MPC 多方；PIR 用户对库的索引隐私。</li><li>平凡解是下载全部；协议换通信量。</li><li>不替代匿名网络。</li><li>下一课 Tor。</li><li>出处：Chor, Goldreich, Kushilevitz and Sudan, 1998。</li></ul>',8))])}const I=o(c,[["render",P]]);export{A as __pageData,I as default};
